function isPlainOptionsObject(v: unknown): v is Record<string, unknown> {
  if (v === null || typeof v !== 'object') return false;
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return false;
  if (v instanceof Tensor) return false;
  const proto = Object.getPrototypeOf(v);
  return proto === Object.prototype || proto === null;
}

function createAtenOpCaller(opName: string): (...args: unknown[]) => unknown {
  return (...args: unknown[]) => {
    let kwArgs: Record<string, unknown> | undefined;
    let posArgs = args;
    if (args.length > 0 && isPlainOptionsObject(args[args.length - 1])) {
      kwArgs = args[args.length - 1] as Record<string, unknown>;
      posArgs = args.slice(0, -1);
    }
    const raw = native.callOpAuto(opName, posArgs, kwArgs);
    return wrapResult(raw);
  };
}

const cache = new Map<string, (...args: unknown[]) => unknown>();

export const aten: AtenOps & Record<string, (...args: unknown[]) => unknown> = new Proxy(
  {} as AtenOps & Record<string, (...args: unknown[]) => unknown>,
  {
    get(_target, prop) {
      if (typeof prop !== 'string') return undefined;
      let fn = cache.get(prop);
      if (!fn) {
        fn = createAtenOpCaller(prop);
        cache.set(prop, fn);
      }
      return fn;
    },
  }
);
